D = 0.04;
L = 100;
rho = 850;
mu = 0.01;
eps = 4.5e-5;

Q = linspace(0.01 ,0.05, 100);

A = pi * D ^ 2 /4;
V = Q /A ;
Re= rho * V * D / mu;

dp = zeros(size (Q));
for k = 1:length(Q)
    f = friction_factor (Re(k), eps , D);
    dp(k) = f * (L/D) * (rho * V(k)^2 /2);
end
figure; %[output:5e3f8f4b]

plot (Q, dp/1000, 'b-', 'LineWidth',1); %[output:5e3f8f4b]
xlabel('Flow rate, Q (m^3/s)'); %[output:5e3f8f4b]
ylabel('Pressure drop (kPa)'); %[output:5e3f8f4b]
title('Pressure Drop vs. Flow Rate'); %[output:5e3f8f4b]
grid on; %[output:5e3f8f4b]


function f = friction_factor (Re, eps, D)

if Re <2300 
    f = 64/Re ;
else 

    f = 0.25 /(log10(eps/(3.7*D) + 5.74/Re^0.9))^2;
end
end


